import{z as i,x as E,o as t,c as u,q as n,j as l,D as a,d as e,s,S as d,b as o}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"Dropout 在 Transformer","description":"","frontmatter":{"title":"Dropout 在 Transformer","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dropout-transformer.md","filePath":"llm/dropout-transformer.md","lastUpdated":1791063341000}'),m={name:"llm/dropout-transformer.md"};function A(B,r,D,f,h,c){const p=E("Mermaid");return t(),u("div",null,[r[2]||(r[2]=n('<h1 id="dropout-在-transformer" tabindex="-1">Dropout 在 Transformer <a class="header-anchor" href="#dropout-在-transformer" aria-label="Permalink to &quot;Dropout 在 Transformer&quot;">​</a></h1><div class="epigraph"><p>训练时随机把一部分激活置零并rescale，等于在指数多种子网络上取平均；推理时用全图，权重已经见过噪声。</p><footer>—— Srivastava et al., Dropout: A Simple Way to Prevent Neural Networks from Overfitting, JMLR 2014；位置见 Vaswani et al., NeurIPS 2017</footer></div><p><a href="/llm/output-init-logit-scale">上一课</a>把第 0 step 的 logit 尺度钉住。缺口从「能不能走第一步」转到「走起来之后如何正则」。Transformer 原论文在残差分支、嵌入与注意力权重上用 dropout；当代大模型预训练常常把比率降到 0 或接近 0，因为数据已远大于参数、欠拟合才是主矛盾。本课写清 <strong>dropout 在块里的位置与缩放</strong>，不把「原论文用了 0.1」写成今天的默认。后课再拆注意力内部的 dropout 与 drop-path，它们不是同一条边。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Srivastava 等人把 dropout 写成：以概率 \\(p\\) 把单元置零，其余乘 \\(1/(1-p)\\)（inverted dropout），使期望与推理时全开一致。对全连接层，这近似于对权重施加噪声、并在子网络集合上 bagging。Transformer 的残差流不是多层感知机的逐层覆盖：子层输出要加回主干。若在主干上 dropout，等于随机把已经学到的身份通路掐断，深度一大，残差公路名存实亡。若只在 \\(F(x)\\) 上 dropout，噪声进增量、公路仍在。Vaswani 等人的选择是后者，外加嵌入后、位置编码后的 dropout。</p><p><span class="marginnote">直觉类比：主干 \\(x\\) 是高速公路，子层 \\(F\\) 是匝道上的加工厂。dropout 放在 \\(F\\) 出口，等于偶尔给加工厂断电，工厂学会让每件产出都别太关键；放在主干上等于随机封路，层数一多车流全线瘫痪——这就是「残差公路名存实亡」的意思。</span></p><p>当代缺口是：<strong>预训练还要不要它</strong>。数据重复少、token 预算按 Chinchilla 给够时，残差 dropout 往往伤害损失；微调数据小、要防记死时，它又回来。本课不选边，只要求配方写明作用点与 \\(p\\)，以及推理必须关闭。</p><p><span class="marginnote">inverted dropout 把 \\(1/(1-p)\\) 放在训练图里。若训练不 rescale、推理再乘 \\((1-p)\\)，检查点与推理代码必须成对。混用两种约定，等于把残差增量整体缩放，深度缩放课刚钉住的 \\(1/\\sqrt{L}\\) 会被静默改写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标准解码器块（Pre-LN）里与 dropout 相关的边：</p><ol><li>注意力加权之后、输出投影之后：对 \\(F_{\\mathrm{attn}}\\) dropout，再加回主干。</li><li>FFN 输出之后：对 \\(F_{\\mathrm{ffn}}\\) dropout，再加回主干。</li><li>嵌入 + 位置之后：对进入第一层的表示 dropout。</li></ol><p>注意力<strong>分数</strong>上的 dropout（对 \\(A\\) 的元素置零再重新归一化或直接置零）下一课单独写。不要把 (1) 和分数 dropout 用同一个 \\(p\\) 糊成「attention dropout=0.1」。</p><p>\\(p\\) 的数量级：原论文 0.1；GPT-2 仍保留；Llama 一类大规模预训练常用 0。微调 / 指令跟随若过拟合训练集，再从 0.0–0.1 扫，不要从预训练检查点的 \\(p\\) 推断微调 \\(p\\)。Drop 与学习率耦合：同样 \\(\\eta\\)，更大的 \\(p\\) 等于更小的有效更新，扫 \\(\\eta\\) 时必须固定 \\(p\\)。</p>',13)),(t(),l(d,null,{default:a(()=>[s(p,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%BD%93%E5%89%8D%E9%98%B6%E6%AE%B5%22%5D%20--%3E%20A%5B%22%E5%A4%A7%E8%A7%84%E6%A8%A1%E9%A2%84%E8%AE%AD%E7%BB%83%3Cbr%3Etoken%20%E6%95%B0%E8%BF%9C%E8%B6%85%E5%8F%82%E6%95%B0%22%5D%0A%20%20A%20--%3E%20P0%5B%22p%20%3D%200%20%E6%88%96%E6%8E%A5%E8%BF%91%200%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E5%B0%8F%E6%95%B0%E6%8D%AE%E5%BE%AE%E8%B0%83%3Cbr%3E%E9%AA%8C%E8%AF%81%E7%BC%BA%E5%8F%A3%E5%8F%98%E5%A4%A7%22%5D%0A%20%20B%20--%3E%20P1%5B%22%E4%BB%8E%200.0%E2%80%930.1%20%E6%89%AB%20p%22%5D%0A%20%20P1%20--%3E%20FIX%5B%22%E6%89%AB%20%CE%B7%20%E6%97%B6%E5%9B%BA%E5%AE%9A%20p%22%5D%0A%20%20P0%20--%3E%20EVAL%5B%22%E6%8E%A8%E7%90%86%E5%85%B3%E9%97%AD%20dropout%22%5D%0A%20%20P1%20--%3E%20EVAL%0A"})]),fallback:a(()=>[...r[0]||(r[0]=[e(" Loading... ",-1)])]),_:1})),r[3]||(r[3]=n('<p><span class="marginnote">数字实例：\\(p=0.1\\) 时每个激活有十分之一概率被丢，留下的乘 \\(1/0.9\\approx 1.11\\)。若错误地把它打在主干而不是 \\(F\\) 上，层数 \\(L=32\\) 时每次前向约有 \\(0.9^{32}\\approx 3.4\\%\\) 的概率恒等支路一点没碰——身份通路被反复打断，深网立刻难训。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>残差上的 dropout 使每次前向的 \\(F\\) 是随机子网络。反向只沿未置零的坐标走，被 drop 的坐标梯度为 0。期望上参数仍收到梯度，但方差增大，与大 batch 降噪对冲。这解释了为何大数据、大 batch 预训练不需要它：噪声已经来自数据，再 drop 只是少算 FLOPs 却加方差。</p><p>与权重衰减不同：衰减是确定性地把 \\(\\|W\\|\\) 往 0 拉；dropout 是激活噪声。两者可叠，但诊断过拟合时应分开关。LN / RMSNorm 通常不 dropout 其 \\(\\gamma,\\beta\\)——对两个向量做 Bernoulli 没有 Srivastava 的平均解释，只会破坏归一化尺度。</p><p>推理关闭 dropout 之后，网络是训练时子网络的近似期望。若训练图忘了 rescale，推理会系统性比训练「更大」，表现为 CE 训练/验证差一截却不是泛化，而是尺度 bug。验收应在 \\(p\\gt 0\\) 的短训上对比「train 模式 vs eval 模式」的 CE，差应来自噪声而不是整体平移。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不管 DropConnect、LayerDrop（整层丢掉）和 drop-path；后两者改变深度，下一课。也不把 dropout 当数值稳定工具：它不抑制 logit 增长，有时因噪声让尖峰更密。确定性训练课会要求固定 RNG；这里只要求：同一公式、同一 \\(p\\)、同一 inverted 约定。</p><p><span class="marginnote">「DropConnect 丢边、LayerDrop 丢整层」的区分：dropout 丢的是激活（单元），DropConnect 丢的是权重（边），LayerDrop 训练时随机跳过整个子层。三者名字像，作用对象分别是激活、参数、深度，诊断与调参方式完全不同。</span></p>',8)),(t(),l(d,null,{default:a(()=>[s(p,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E4%B8%BB%E5%B9%B2%20x%22%5D%20--%3E%20F%5B%22%E5%AD%90%E5%B1%82%20F%22%5D%0A%20%20F%20--%3E%20D%5B%22dropout%20inverted%22%5D%0A%20%20D%20--%3E%20ADD%5B%22x%20%2B%20drop(F)%22%5D%0A%20%20X%20--%3E%20ADD%0A%20%20ADD%20--%3E%20Y%5B%22%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E5%B1%82%22%5D%0A"})]),fallback:a(()=>[...r[1]||(r[1]=[e(" Loading... ",-1)])]),_:1})),r[4]||(r[4]=o("h2",{id:"小结",tabindex:"-1"},[e("小结 "),o("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),r[5]||(r[5]=o("ul",null,[o("li",null,"Transformer 的默认 dropout 打在残差增量 \\(F\\) 与嵌入后，不打在 Pre-LN 主干公路上。"),o("li",null,"inverted dropout 的 rescale 必须在训练图里；否则与深度缩放、推理尺度冲突。"),o("li",null,"大规模预训练常取 \\(p=0\\)；微调过拟合时再扫，不与预训练共用一个「论文默认 0.1」。"),o("li",null,"分数 dropout、drop-path 不是本课这条边。"),o("li",null,"出处：Srivastava et al., JMLR 2014；Vaswani et al., NeurIPS 2017。")],-1))])}const T=i(m,[["render",A]]);export{g as __pageData,T as default};
